            [600] = new Dictionary<int, string>
            {
                [342389] = "Click to select Nanomage Male.",
                [770493] = "Character problem. Contact support.",
                [1622994] = "The Morning Star Transfer Station",
                [2457557] = "Select your character's appearance",
                [7564900] = "Click to inspect the Bureaucrat.",
                [11350309] = "Difficulty to play: <FONT color=\"#ffff00\"> High </FONT>\r\nThe Shade is a mix between a predator and a parasite. Dark and aggressive, the Shade utilizes nano-technology to suck the life and energy out of their prey, robbing them of the basic elements they need to subsist. The Shade stays out of harm's way by relying on concealment and good combat mobility. By using the element of surprise, the Shade can inflict large amounts of damage in a short amount of time.",
                [11734740] = "Difficulty to play: <FONT color=\"#ffff00\"> High </FONT>\r\nAn Agent&#8217;s life is spent in the shadows. Agents focus on concealment and subterfuge skills and one of their special abilities is going undercover. Doing so enables them to use nanotechnology normally only available to other professions. When it comes to combat, the Agent&#8217;s speciality is sniping opponents with high velocity rifles using unique nanotechnology to further increase the damage.",
                [12179522] = "Difficulty to play: <FONT color=\"#ffff00\"> Medium </FONT>\r\nA Fixer specializes in getting people what they need when they need it.  By hacking into what is known as The Grid from anywhere in the world, Fixers can use it to transport themselves or their entire team in digital form around Rubi-Ka. The Fixers move fastest of all and special armors make them the hardest to hit as well. A Fixer's main combat strategy lies in limiting the maneuverability of opponents and they favour weapons from the sub-machinegun category.",
                [13618949] = "Select face.",
                [13634964] = "Account is locked.",
                [18488884] = "Nano Technician Selected.",
                [24135060] = "Character not found.",
                [24169982] = "Click to inspect the Nano Technician.",
                [24541365] = "Boarding shuttle to Omni-1",
                [27330865] = "Continuing to DNA construction area",
                [27519330] = "Click to inspect the Adventurer.",
                [31587506] = "Slender.",
                [32335924] = "Keeper Selected.",
                [35129054] = "The Nanomage is unique to Rubi-Ka, genetically engineered for the notum-rich environment, and thus unable to live anywhere else in the galaxy. The Nanomage has a strong advantage in using nanotechnology and metaphysics.",
                [41516260] = "Opifex Male selected.",
                [42695918] = "Click to proceed to Profession selection.",
                [46271652] = "by selecting a face, body height, and body type. Your character's appearance does not influence the gameplay in any way. When you have made your choices, click Next.",
                [47929166] = "The Solitus is the galaxy's most common breed - a direct natural descendant of the Homo Sapiens which evolved during Earth's long winter. The Solitus has no specific advantage, but is capable of adapting to almost any situation and environment, and has a proclivity for learning.",
                [51780996] = "Solitus Female selected.",
                [52480948] = "Select your character's profession",
                [52620036] = "Suggest name.",
                [55564820] = "Digits can only be used at the end of the name and only after the 4th char.",
                [56161934] = "Character already logged in.",
                [58751332] = "Difficulty to play: <FONT color=\"#ffff00\"> High </FONT>\r\nThe Bureaucrat brings order to chaos. Bureaucrats have very limited weapon skills but their vast knowledge of nanotechnology makes up for that. They use it to directly damage opponents and create robots that will fight for them. But most importantly, a Bureaucrat uses nanotechnology to boost his leadership skills and to control hostile beings, bending their minds and blurring their aims. In a team situation, a Bureaucrat is therefore a natural leader.",
                [60879742] = "S E L E C T   P R O F E S S I O N",
                [63701108] = "Shade Selected.",
                [67416068] = "Player not found.",
                [72416866] = "Difficulty to play: <FONT color=\"#ffff00\"> Low / Medium </FONT>\r\nAn Adventurer's soul is at home in the wild. Adventurers study the animals, learn their ways and gain some of their abilities along the way. Their weapon skills are well balanced with equal advancement opportunities in melee and ranged combat. They also become skilled at using nanotechnology to withstand damage or to create metaphysical cloaks that damage their aggressors. An Adventurer is an excellent healer, only truly rivaled by the Doctor.",
                [72444052] = "Trader Selected.",
                [76728164] = "Atrox selected.",
                [80046117] = "Click to select Nanomage Female.",
                [82048901] = "S E L E C T   A P P E A R A N C E",
                [83594021] = "Please board the shuttle to Rubi-Ka, secure yourself and enjoy the ride!\r\nShortly you will find yourself in the Arrival Hall in the spaceport of Omni-1.",
                [85960868] = "Bureaucrat Selected.",
                [90551204] = "Account has illegal password.",
                [93730238] = "Account already in use, character logged in.",
                [93888884] = "Adventurer Selected.",
                [94046782] = "The Opifex is genetically engineered to be a fast and agile breed, at the expense of its strength and stamina. The Opifex is versatile and has spread wide across the galaxy. The Opifex makes for a good agent, fixer or martial artist, where speed and precision is beneficial.",
                [98043122] = "No server with correct RDB.",
                [100026692] = "Click to set your character's height to Short.",
                [103286066] = "Click to set your character's body type to Slender.",
                [103616948] = "Nanomage Female selected.",
                [105053140] = "by clicking on any of the fourteen profession buttons. Each profession has its advantages and disadvantages. A detailed description can be found when clicking the profession buttons. When you have made your choice click Next.",
                [106904827] = "Go Back.",
                [107050200] = "Click to select Atrox.",
                [107121557] = "Click to select Solitus Female.",
                [107443049] = "Heavy.",
                [108018980] = "Short.",
                [108184756] = "Docking procedure completed",
                [108214510] = "Difficulty to play: <FONT color=\"#ffff00\"> Medium </FONT>\r\nA Nano Technician is an expert user of aggressive nanotechnology. Nano Technicians are experts at using nanotechnology to deal explosive area-of-effect damage and the types of damage they can manage is incomparable. They are also capable of using other kinds of nanotechnology and can for example warp themselves between locations. Nano-Technicians must be devoted to nanotechnology skills and as a result, physical and weapon skills will suffer.",
                [108549524] = "Nickname is invalid or reserved.",
                [108956596] = "Solitus Male selected.",
                [111071483] = "Choose a nickname.",
                [111591508] = "Click to inspect the Martial Artist.",
                [112774212] = "S E L E C T   B R E E D",
                [115820932] = "Opifex Female selected.",
                [116636116] = "Click to inspect the Metaphysicist.",
                [118218323] = "Checking credentials...\r\n",
                [119893348] = "Fixer Selected.",
                [122709390] = "Nickname is already in use.",
                [123574717] = "Medium.",
                [125021838] = "Breed: %s\r\nProfession: %s",
                [128396253] = "Medium.",
                [128765541] = "Click to select Opifex Male.",
                [131506020] = "Difficulty to play: <FONT color=\"#ffff00\"> Low </FONT>\r\nWhen it comes to dishing out raw combat damage a Martial Artist outshines all other professions. Fighting unarmed, the Martial Artist's main strength lies in special attacks, knowing how to cripple opponents by attacking their weak spots. The Martial Artist is also a very proficient healer, truly surpassed by only the Doctor and the Adventurer.",
                [137916099] = "Difficulty to play: <FONT color=\"#ffff00\"> Medium / High </FONT>\r\nThe Meta-Physicists get their strength from the \"other side\". They can manifest their emotions in the material world and eventually control multiple materialized entities and use them in combat. The uniqueness of a Meta-Physicist lies in manipulating the underlying fabric of the world where nanotechnology operates, adjusting the nanotechnology skills of friends and foes alike. Their weapon skills are poor but they can use their powers to damage their opponents directly.",
                [137986779] = "Click to go back to Profession selection.",
                [140082788] = "Geosynchronous orbit around Rubi-Ka",
                [152027794] = "Click to inspect the Doctor.",
                [155299122] = "Click to inspect the Keeper.",
                [156926699] = "Click to go back to Appearance selection.",
                [156977540] = "Click to proceed to name selection.",
                [161383857] = "Click this button to finish character creation and start in Rubi-Ka.\r\nYour character will be transferred to the ICC Shuttleport.\r\n\r\nOnce you click this button, you can no longer edit your character's breed, appearance, profession or name!\r\n\r\n(The Shadowlands professions Keeper and Shade cannot start in Rubi-Ka.)",
                [163071938] = "Difficulty to play: <FONT color=\"#ffff00\"> Medium / High </FONT>\r\nAn Engineer is a specialist in creating all sorts of machinery. Engineers really excel in constructing powerful battledroids and have access to unique nanotechnology to enhance and repair them. The Engineer's weapon skills are not that great, but the Engineer/robot-pet duo is quite formidable. All Engineers learn to create powerful protective shields and the best Engineers can hack into satellites, and use them to teleport any member of the team to the Engineer's location.",
                [163481026] = "Difficulty to play: <FONT color=\"#ffff00\"> Low </FONT>\r\nAn Enforcer specializes in close combat using raw power and naked rage to subdue opponents. Enforcers are physically better suited than all others to sustain damage and can learn some protective nanotechnology to further increase their chances of survival. Their brutality and in-your-face combat attitude normally make them the prime targets for any opponent. Enforcers utilize this for the good of the team and rely largely on others to heal them.",
                [163999213] = "Click to set your character's height to Medium.",
                [164305064] = "Click to finish character creation. Once you click finish you can no longer edit your character's breed, appearance, profession or name!",
                [164658644] = "Please choose a Breed.",
                [165810482] = "Click to inspect the Trader.",
                [169342932] = "Player has illegal password.",
                [170145658] = "Nickname:",
                [171771173] = "Click the two arrows repeatedly to select a face.",
                [172602036] = "Nanomage Male selected.",
                [176437060] = "Soldier Selected.",
                [177133309] = "The name can only contain alphabetic chars or digits. And no character after a digit.",
                [177652275] = "Can't create more characters.",
                [181436052] = "Select build",
                [183066372] = "Click to have the server suggest a name for your character. If the suggested name is not to your liking, click the button again. You can modify a suggested name by editing it in the text entry box.",
                [183833282] = "Difficulty to play: <FONT color=\"#ffff00\"> High </FONT>\r\nThe Trader is the ultimate entrepreneur, getting more for less in every single transaction. Like others, they create and trade material goods. But in combat situations, they use unique nanotechnology which enables them to drain opponents of skills, energy and health, transfering those benefits to themselves or their allies. This frequently causes the most formidable opponents to wither to a cracked shell of their former self.",
                [185671390] = "Contact administration.",
                [187855237] = "Click to select Opifex Female.",
                [189712468] = "Colonist cleared for passage!\r\n",
                [190301160] = "Finish.",
                [191255476] = "Exit Character Creation.",
                [191315100] = "Tall.",
                [191352900] = "Next.",
                [192016820] = "Click to go back to Breed selection.",
                [195917652] = "Select head",
                [196649904] = "Select your character's breed by clicking on the breed models. Each breed offers different advantages and disadvantages. Learn more by selecting a breed. When you have made your choice click Next.",
                [196674932] = "When you are satisfied with your selection, click to proceed to appearance selection.",
                [200852322] = "Difficulty to play: <FONT color=\"#ffff00\"> Medium </FONT>\r\nA Doctor is really a biotechnology specialist. The Doctors' prime skills focus mainly on healing and protecting but they also learn how to produce and administer powerful biotoxins that slow, weaken and wear down their opponents. Limited weapon skills can lead to a bumpy ride when going solo, but in a team the Doctor really shines. When chaos descends on the team in combat, its survival usually lies squarely on the Doctor's shoulders, so this profession is not for the faint-hearted.",
                [204746788] = "Martial Artist Selected.",
                [207007426] = "Difficulty to play: <FONT color=\"#ffff00\"> Medium </FONT>\r\nThe Keeper is a fighter that radiates valour and heroism - a beacon of light and hope to the team. A formidable opponent who specialises in close combat, the Keeper is especially proficient wielding two-handed edged weapons. This profession's uniqueness lies in the ability to share life and diverse powers with nearby allies.",
                [207344627] = "Click this button to finish character creation and start in the Shadowlands.\r\nYour character will be transferred to the Jobe research facilities.\r\n\r\nOnce you click this button, you can no longer edit your character's breed, appearance, profession or name!\r\n\r\n(You need the Shadowlands expansion pack to start in the Shadowlands.)",
                [207923652] = "Engineer Selected.",
                [213881643] = "Getting suggested nickname...\r\n",
                [214125134] = "The server is down.",
                [218721543] = "Click this button to finish character creation and start in Arete Landing. Your character will be transferred to Arete Landing. Once you click this button, you can no longer edit your character's breed, appearance, profession or name!",
                [224353244] = "Click to set your character's height to Tall.",
                [225957460] = "Select height",
                [229364195] = "The name must contain more than 3 characters and less than 13.",
                [230137493] = "Click to select Solitus Male.",
                [234353508] = "Agent Selected.",
                [234583117] = "Click to set your character's body type to Medium.",
                [235147346] = "Click to inspect the Soldier.",
                [235785269] = "You must enter a name before you can proceed!",
                [240934557] = "Something is wrong with the server.",
                [244592482] = "Difficulty to play: <FONT color=\"#ffff00\"> Low / Medium </FONT>\r\nA Soldier strives for excellence in armed combat. The skill advancement of Soldiers focuses entirely on assault and survival. They use unique nanotechnology to protect their bodies, enhance reflexes, weapon skills and their armor. Perhaps most importantly, Soldiers are able to create strong damage absorption shields around themselves which make them partly invulnerable and even reflect some of the damage back to the attacker.",
                [245803508] = "Enforcer Selected.",
                [246788914] = "Click to inspect the Engineer.",
                [247296306] = "Click to inspect the Enforcer.",
                [248489460] = "Account not paid.",
                [252555380] = "Metaphysicist Selected.",
                [260098452] = "Doctor Selected.",
                [260210404] = "Click to inspect the Agent.",
                [260745330] = "Click to inspect the Fixer.",
                [260793573] = "E N T E R   N A M E",
                [261898517] = "Click to inspect the Shade.",
                [262052372] = "All your selections will be saved untill next time you enter.",
                [262139760] = "Type in a name for your character in the text entry box. You can have the server generate a name for your character by clicking the Suggest Name Button. Note that your character's name needs to be unique. You will be notified if your chosen name has already been taken.",
                [264418457] = "Click to set your character's body type to Heavy.",
                [264892014] = "The Atrox is unique to Rubi-Ka, and was genetically engineered to be a manual laborer in the notum mines. The excessive manipulation led to the Atrox being a genderless breed. The Atrox is strong, hardy and resilient, and makes for a good soldier or worker.",
            },
