                [35405658] = "Voices volume:",
                [35475521] = "Equals the chat command '/pet behind'. Makes your pet (except towers) stand behind you, aborting all attacks. It will not attack anyone that attacks you. It will not return fire on itself.",
                [35475522] = "Equals the chat command '/pet follow'. Makes your pet (except towers) follow you. It will not attack anyone that attacks you. It will not return fire on itself.",
                [35475523] = "Equals the chat command '/pet guard'. Makes your pet follow you and instantly attack anyone that attacks you. It will move on to the next fighting target once it has finished with the first.",
                [35475524] = "Equals the chat command '/pet heal'. A special Meta-Phycesist heal-pet command, that makes the pet start a heal-cycle on your current nano-target.",
                [35475525] = "Equals the chat command '/pet hunt'. Makes the pet roam around looking for a target to attack. When it has killed everything it can see (or after some time), it returns.",
