                [107] = "The Two Handed (2h) Blunt Weapon Skill allows you to use 2hb Weapons and increases your attack rating when wielding 2hb Weapons. Dependencies: 50%Strength, 50% Stamina",
                [108] = "The Thrown Weapons Skill allows you to use thrown weapons and increases your attack rating when wielding thrown weapons. Dependencies 60% Agility, 20% Strength 20% Sense.",
                [109] = "The Grenade Skill allows you to use grenade based weapons and increases your attack rating when wielding grenade based weapons. Dependencies: 40%Agility, 40% Sense, 20% Intelligence",
                [110] = "The Heavy Weapons Skill allows you to use Heavy Weapons and increases your attack rating when wielding Heavy Weapons.  Dependencies: 60% Agility, 40% Strength.",
