                [120] = "The physical prowess initiative skill is used to increase the speed of your martial art attacks.  Dependencies 60% Sense, 20% Psychic, 10% Intelligence, 10% Agility",
                [121] = "The bow special attack skill is a skill used to equip weapons that have the Bow special attack ability. The higher your skill in bow special attack the more effective these special attacks will be. Dependencies:  50% Agility, 40% Sense and 10% Strength.",
                [122] = "Sensory improvement is a skill used for learning and casting Nano formulas that use Sensory improvement as a requirement. If a nano formula is offensive and carries a skill check that is based off Sensory improvement then the higher this skill the higher the chance will be of the attack landing on your target.  Dependencies: Intelligence 80%, Strength 20%.",
                [123] = "First aid allows you to use health and nano point stim injectors that can be bought from medical vendors  Dependencies: 40% Sense, 30% Intelligence, 30% Agility",
                [124] = "Treatment allows you to use health and nano point treatment kits that can be bought from medical vendors. It is also used to determine what level of implants you can equip. Dependencies: 50% Intelligence, 30% Agility and 20% Sense",
                [125] = "Mechanical engineering is the tradeskill focusing on motors and other mechanical objects.  Dependencies: Intelligence 50%, Agility 50%",
                [126] = "Electrical engineering is a tradeskill mainly used in the production of electrical appliances and components.  Dependencies: Intelligence 50%, Agility 30%, Stamina 20%",
                [127] = "Matter Metamorphosis is a skill used for learning and casting Nano formulas that use Matter Metamorphosis as a requirement. If a nano formula is offensive and carries a skill check that is based off Matter Metamorphosis then the higher this skill the higher the chance will be of the attack landing on your target.   Dependencies: Intelligence 80%, Psychic 20%",
                [128] = "Biological metamorphosis is a skill used for learning and casting Nano formulas that use Biological metamorphosis as a requirement. If a nano formula is offensive and carries a skill check that is based off Biological metamorphosis then the higher this skill the higher the chance will be of the attack landing on your target.  Dependencies: Intelligence 80%, Psychic 20%",
                [129] = "The nano skill psychological modifications is a skill used for learning and casting Nano formulas that use psychological modifications as a requirement. If a nano formula is offensive and carries a skill check that is based off psychological modifications then the higher this skill the higher the chance will be of the attack landing on your target.  Dependencies: Intelligence 80%, Sense 20%",
                [130] = "Matter creation is used to make matter appear from energy, the basic functioning of the nano bots.  Dependencies: Intelligence 80%, Stamina 20%.",
                [131] = "Time and space is the nano skill used to run nano programs affecting time and space.  Dependencies: Intelligence 80%, Agility 20%.",
                [132] = "This skill defines, along with profession, character level and breed, how much Nano Energy you have.  Dependencies: 70% Psychic, 10% Sense, 10% Intelligence, 10% Stamina",
                [133] = "The ranged energy weapon skill allows you to use Ranged Energy Weapons and increases your attack rating when wielding Ranged Energy Weapons. Dependencies: 40% Psychic, 40% Sense, 20% Intelligence",
                [134] = "The multiple wield ranged weapons skill allows you to equip a weapon with this requirement in your off hand  Dependencies: 60% Agility, 40% Intelligence",
                [135] = "Trap disarmament is of course used to disarm traps.  It is also used in conjunction with perception to detect traps.  Dependencies: Sense 60%, Intelligence 20% and Agility 30%.",
                [136] = "Perception is the core skill used in detecting things, be it concealed people, hidden objects or traps.  Dependent on Sense 70% and Intelligence 30%.",
                [137] = "Adventuring enables the character to access different backpacks and some special items. Dependencies: 20% Strength, 50% Agility, 30% Stamina",
                [138] = "Swim speed effects how fast you can swim.  Dependencies 20% Agility, 60% Stamina  20% Strength.",
                [139] = "This skill enables the driver to access airborne vehicles. Dependencies: 60% Sense, 20% Intelligence, 20% Agility",
                [140] = "This skill is used to determine what type of map implants you can use, and how much information you get from them.  Map implants can be bought from map vendor terminals and offer such upgrades as being able to see monsters on the mini-map.\r\n\r\nDependencies: Sense 50%, Intelligence 40%, Psychic 10%",
                [141] = "Tutoring is a skill that allows you to use the tutoring devices that can be found on Rubi-Ka. These devices can be used to temporarily transfer tradeskill knowledge to another person.  Dependencies: 70% Intelligence, 20% Sense, 10% Psychic",
                [142] = "Brawling is a skill used to equip weapons that have the Brawl special attack ability. The higher your skill in Brawl the more effective these special attacks will be. Note that Brawl is also enabled inherently when using no weapons (i.e. hand to hand combat)  Dependencies: 60% Strength, 40% Stamina",
                [143] = "Riposte is used to equip some Martial Art special attacks and some special devices. Dependencies: 50% Agility, 50% Sense",
                [144] = "Dimach is a skill used to equip weapons that have the Dimach special attack ability. The higher your skill in Dimach the more effective these special attacks will be. Note that Dimach is also enabled inherently when using no weapons (i.e. hand to hand combat) Dependencies: 80% Sense, 20% Psychic",
                [145] = "Deflect is a requirement for equipping certain weapons and combat based items. Deflect increases the chance for a glancing blow.  Depenedencies: 50% Strength, 20% Agility, 30% Sense",
                [146] = "Sneak attack is a skill used to equip weapons that have the Sneak attack special attack ability. The higher your skill in sneak attack the more effective these special attacks will be. Dependedncies: 80% Sense, 20% Psychic",
                [147] = "Fast attack is a skill used to equip weapons that have the Fast Attack special attack ability. The higher your skill in fast Attack the more effective these special attacks will be. Dependencies: 60% Agility, 40% Sense",
                [148] = "Burst is a skill used to equip weapons that have the Burst special attack ability. The higher your skill in Burst the more effective these special attacks will be.  Defined by: Agility 50%, Strength 30%, Stamina 20%",
                [149] = "The nano program initiative skill is used to more quickly execute nano programs.  Dependencies: 60% Sense, 40% Agility",
                [150] = "The fling shot is a skill used to equip weapons that have the fling shot special attack ability. The higher your skill in fling shot the more effective these special attacks will be.   It is 100% dependent on Agility.",
                [151] = "Aimed shot is a skill used to equip weapons that have the Aimed Shot special attack ability. The higher your skill in Aimed Shot the more effective these special attacks will be. Dependency: 100% Sense",
                [152] = "Body development defines your health, or hit points.  It is exclusively dependant on Stamina.  Your character level, your profession, and your breed also influences your health.",
                [153] = "The duck skill is the one used to determine if you are hit by certain types of weapons, most commonly shotguns.  Dependencies: 50% Agility, 30% Sense, 20% Intelligence.",
                [154] = "The Dodge Ranged skill is the one used to determine if you are hit by certain types of weapons or attacks, in this case most common ranged weapons.  Dependencies 50% Agility, 30% Sense, 20% Intelligence",
                [155] = "The evade close combat attack skill is the one used to determine if you are hit by certain types of weapons or attacks, in this case Melee and Martial arts attacks.  Dependencies: 50% Agility, 30% Sense, 20% Intelligence.",
                [156] = "The run speed skill defines how fast your character can move. Dependencies: 40% Agility, 40% Stamina, 20% Strength",
                [157] = "Quantum forcefield technics is a tradeskill used to make quantum based components.  Dependencies: Intelligence 50%, Psychic 50%",
                [158] = "Weapon smithing is a tradeskill used primarily in the production of weapons and weapon upgrades.  Dependencies: Intelligence 50%, Strength 50%.",
                [159] = "Pharmaceutical tech is a tradeskill primarily used to make medicines and stims.  Dependencies: Intelligence 80%, Agility 20%",
                [160] = "Nano programming is a tradeskill used primarily in the production of Implants and Nano programs.  Dependencies: Intelligence 100%",
                [161] = "Computer literacy is the skill that allows you to use better computer equipment like belts and NCU units. It also determines which entrances and exits you can use in the grid   Dependencies: Intelligence 100%.",
                [162] = "Psychology is used as a skill check in the charm line of nano formulas. It is also used in some tradeskill processes. Dependencies: Intelligence 50%, Sense 50%",
                [163] = "Chemistry is a tradeskill primarily used in the production of chemicals and other components.  Dependencies: Stamina 50%, Intelligence 50%",
                [164] = "Concealment is a skill used to hide from observation.  Dependencies: Sense 70% and Agility 30%.",
                [165] = "Breaking and entering is a skill used to open locked doors and other locked devices.  Dependencies: Agility 40%, Sense 30% and Psychic 30%.",
                [166] = "A skill which defines what type of ground vehicle you can use.  Dependencies: Sense 60%, Intelligence 20%, Agility 20%",
                [167] = "The Full Auto skill is a skill used to equip weapons that have the Full Auto special attack ability.  The higher your skill in Full Auto, the more effective these special attacks will be.  Dependencies: 60% Strength, 40% Stamina.",
                [168] = "Your Nano Formula Resist skill decides how well you resist hostile Nano Programs. Raising this skill will help you to occasionally resist nano based attacks. Dependencies:  Intelligence 20%, Psychic 80%.",
            },
